bash -lc cat > /mnt/data/create_new_slide.js <<'NODE'
const pptxgen = require('pptxgenjs');
const { warnIfSlideHasOverlaps, warnIfSlideElementsOutOfBounds } = require('/home/oai/skills/slides/pptxgenjs_helpers/layout');
const pptx = new pptxgen();
pptx.layout = 'LAYOUT_WIDE';
pptx.author = 'OpenAI';
pptx.subject = 'New PPT page';
pptx.title = '四大核心技术';
pptx.company = 'OpenAI';
pptx.lang = 'zh-CN';
pptx.theme = {
  headFontFace: 'Microsoft YaHei',
  bodyFontFace: 'Microsoft YaHei',
  lang: 'zh-CN'
};
pptx.defineLayout({ name:'WIDE', width:13.333, height:7.5 });
pptx.layout = 'WIDE';
const slide = pptx.addSlide();
slide.background = { color: '071513' };
const W = 13.333, H = 7.5;
const C = {
  bg:'071513', panel:'113630', panel2:'0D2925', panel3:'17433B', line:'4DE3C0', line2:'2AA890', yellow:'FFF2A2', gold:'FFD75A', red:'FF5148', white:'F7FFF9', gray:'C9D8D4', green:'9AFFD9', blue:'79E6FF'
};
function addRect(x,y,w,h,fill,line=C.line,trans=0,rad=false){
  slide.addShape(pptx.ShapeType.roundRect, {x,y,w,h,rectRadius: rad?0.08:0.03, fill:{color:fill, transparency:trans}, line:{color:line, transparency:20, width:1.2}});
}
function addText(txt,x,y,w,h,opts={}){
  slide.addText(txt,{x,y,w,h, fontFace:'Microsoft YaHei', margin:0.04, breakLine:false, fit:'shrink', color:opts.color||C.white, bold:opts.bold||false, fontSize:opts.size||14, align:opts.align||'left', valign:opts.valign||'mid', ...opts});
}
// background tech grid
slide.addShape(pptx.ShapeType.rect,{x:0,y:0,w:W,h:H,fill:{color:C.bg},line:{color:C.bg,transparency:100}});
for(let i=0;i<26;i++){
  const x = 0.2 + i*0.52;
  slide.addShape(pptx.ShapeType.line,{x,y:0.15,w:0,h:H-0.3,line:{color:'0D3D34',transparency:72,width:0.4,dash:'dash'}});
}
for(let i=0;i<15;i++){
  const y = 0.18 + i*0.48;
  slide.addShape(pptx.ShapeType.line,{x:0.15,y,w:W-0.3,h:0,line:{color:'0D3D34',transparency:78,width:0.4,dash:'dash'}});
}
// Top brand/title bar
slide.addShape(pptx.ShapeType.rect,{x:0.15,y:0.18,w:12.98,h:0.78,fill:{color:'09221E',transparency:6},line:{color:C.line,width:1.2,transparency:20}});
slide.addShape(pptx.ShapeType.rect,{x:0.15,y:0.92,w:12.98,h:0.06,fill:{color:C.red},line:{color:C.red,transparency:100}});
addText('CardioPilot',9.65,0.25,2.15,0.46,{size:24,bold:true,color:C.line,align:'right'});
addText('四大核心技术驱动康复管理闭环',0.45,0.28,5.5,0.35,{size:22,bold:true,color:C.yellow});
addText('把“技术卖点”直接对应到患者 / 家属 / 医生的核心痛点',0.48,0.62,5.9,0.20,{size:9.5,color:C.gray});
addText('技术路线总览',11.9,0.34,0.9,0.22,{size:10.5,color:C.yellow,bold:true,align:'right'});
// Main frame
slide.addShape(pptx.ShapeType.roundRect,{x:0.42,y:1.25,w:12.5,h:5.85,rectRadius:0.08,fill:{color:'0B201D',transparency:10},line:{color:C.line,width:1.1,transparency:10}});
// Column headers
slide.addShape(pptx.ShapeType.roundRect,{x:0.75,y:1.48,w:3.45,h:0.44,rectRadius:0.08,fill:{color:'123B34',transparency:0},line:{color:C.line,width:1,transparency:20}});
addText('核心技术优势',0.85,1.56,2.3,0.18,{size:14,bold:true,color:C.yellow,align:'center'});
slide.addShape(pptx.ShapeType.roundRect,{x:4.75,y:1.48,w:7.63,h:0.44,rectRadius:0.08,fill:{color:'123B34',transparency:0},line:{color:C.line,width:1,transparency:20}});
addText('解决的痛点及三方价值',4.95,1.56,4.1,0.18,{size:14,bold:true,color:C.yellow,align:'center'});
['患者','家属','医生'].forEach((r,i)=>{
  addText(r,6.0+i*2.02,1.56,0.75,0.18,{size:12,bold:true,color:C.green,align:'center'});
});
const rows = [
  {no:'01', title:'科学干预方案生成', sub:'聚焦专业，生成科学档案', c:'#3FC0FF', vals:['个性化康复方案\n目标清晰，更安心','降低照护与\n决策压力','提升方案\n制定效率']},
  {no:'02', title:'安全可靠咨询', sub:'降低风险，确保可信回复', c:'#3FE0BE', vals:['专业解答\n减少焦虑，增强信任','随时获取\n权威信息','减少咨询负担\n提升沟通质量']},
  {no:'03', title:'主动智能预警', sub:'底层算法，主动干预能力', c:'#FF9D2E', vals:['风险早发现早干预\n降低恶化风险','及时接收提醒\n应对更从容','及时掌握风险\n并作出干预']},
  {no:'04', title:'长期依从性提升', sub:'异常识别，提高依从性', c:'#9F72FF', vals:['持续支持\n增强信心','更好地\n陪伴支持','减轻长期\n干预负担']},
];
const y0=2.13, rowH=1.13, gap=0.17;
rows.forEach((r,idx)=>{
  const y = y0 + idx*(rowH+gap);
  addRect(0.72,y,3.55,rowH,'0E302B',r.c.replace('#',''),8,true);
  // number block
  slide.addShape(pptx.ShapeType.roundRect,{x:0.88,y:y+0.22,w:0.58,h:0.58,rectRadius:0.08,fill:{color:r.c.replace('#',''),transparency:6},line:{color:r.c.replace('#',''),transparency:0,width:1.2}});
  addText(r.no,0.92,y+0.39,0.5,0.16,{size:16,bold:true,color:'FFFFFF',align:'center'});
  addText(r.title,1.62,y+0.23,2.25,0.25,{size:16,bold:true,color:r.c.replace('#','')});
  addText('— '+r.sub,1.62,y+0.58,2.25,0.22,{size:11.2,color:C.white});
  // arrow
  slide.addShape(pptx.ShapeType.rightArrow,{x:4.36,y:y+0.42,w:0.34,h:0.27,fill:{color:r.c.replace('#',''),transparency:5},line:{color:r.c.replace('#',''),transparency:100}});
  // three value cells
  for(let i=0;i<3;i++){
    const x=4.85+i*2.45;
    slide.addShape(pptx.ShapeType.roundRect,{x,y:y+0.03,w:2.18,h:rowH-0.06,rectRadius:0.06,fill:{color:'102F2A',transparency:idx===2?4:12},line:{color:r.c.replace('#',''),width:1.0,transparency:30}});
    slide.addShape(pptx.ShapeType.ellipse,{x:x+0.12,y:y+0.22,w:0.33,h:0.33,fill:{color:r.c.replace('#',''),transparency:8},line:{color:r.c.replace('#',''),transparency:100}});
    const role = ['患','家','医'][i];
    addText(role,x+0.165,y+0.297,0.22,0.08,{size:10,bold:true,color:'FFFFFF',align:'center'});
    addText(r.vals[i],x+0.53,y+0.22,1.48,0.62,{size:11.0,color:C.white,bold:false,breakLine:false,fit:'shrink'});
  }
});
// Footer summary strip
slide.addShape(pptx.ShapeType.roundRect,{x:1.65,y:7.12,w:10.05,h:0.28,rectRadius:0.06,fill:{color:'133A34',transparency:2},line:{color:C.line,width:0.8,transparency:35}});
addText('从“功能展示”转向“技术价值展示”：科学性、安全性、主动性、依从性',2.1,7.18,9.15,0.12,{size:10.5,bold:true,color:C.yellow,align:'center'});
warnIfSlideHasOverlaps(slide, pptx, { muteContainment: true, ignoreDecorativeShapes: true });
warnIfSlideElementsOutOfBounds(slide, pptx);
pptx.writeFile({ fileName: '/mnt/data/四大核心技术_新页面.pptx' });
