const pptxgen = require('pptxgenjs');
const { warnIfSlideHasOverlaps, warnIfSlideElementsOutOfBounds } = require('/home/oai/skills/slides/pptxgenjs_helpers/layout');
const pptx = new pptxgen();
pptx.defineLayout({ name:'WIDE', width:13.333, height:7.5 });
pptx.layout = 'WIDE';
pptx.author = 'OpenAI';
pptx.subject = '四大核心技术优化版';
pptx.title = '四大核心技术驱动康复管理闭环';
pptx.lang = 'zh-CN';
pptx.theme = {
  headFontFace: 'Microsoft YaHei',
  bodyFontFace: 'Microsoft YaHei',
  lang: 'zh-CN'
};

const slide = pptx.addSlide();
const W = 13.333, H = 7.5;
const C = {
  bg:'071513',
  bg2:'09221E',
  panel:'0E2D28',
  panel2:'123B34',
  panel3:'16463D',
  line:'3FE0BE',
  lineSoft:'2AA890',
  mint:'7DFFD9',
  yellow:'FFF2A2',
  gold:'FFD75A',
  red:'FF5148',
  white:'F7FFF9',
  gray:'BFD3CD',
  gray2:'7FA097',
  dark:'05100E'
};
function addText(txt,x,y,w,h,opts={}){
  slide.addText(txt,{x,y,w,h, fontFace:'Microsoft YaHei', margin:0.02, fit:'shrink', breakLine:false, color:opts.color||C.white, bold:opts.bold||false, fontSize:opts.size||14, align:opts.align||'left', valign:opts.valign||'mid', ...opts});
}
function rect(x,y,w,h,fill,line=C.line,opts={}){
  slide.addShape(pptx.ShapeType.roundRect,{x,y,w,h,rectRadius:opts.radius||0.06,fill:{color:fill,transparency:opts.transparency||0},line:{color:line,width:opts.width||1,transparency:opts.lineTrans||35}});
}
function pill(x,y,w,h,txt,opts={}){
  rect(x,y,w,h,opts.fill||'123B34',opts.line||C.line,{radius:0.08,width:0.75,lineTrans:opts.lineTrans??50,transparency:opts.transparency||0});
  addText(txt,x+0.05,y+0.02,w-0.1,h-0.04,{size:opts.size||8.8,bold:opts.bold||false,color:opts.color||C.white,align:'center'});
}

// Background
slide.background = { color: C.bg };
slide.addShape(pptx.ShapeType.rect,{x:0,y:0,w:W,h:H,fill:{color:C.bg},line:{color:C.bg,transparency:100}});
// Subtle grid, less distracting than previous version
for(let i=0;i<23;i++){
  const x = 0.28 + i*0.58;
  slide.addShape(pptx.ShapeType.line,{x,y:1.05,w:0,h:H-1.25,line:{color:'0D3D34',transparency:82,width:0.35,dash:'dash'}});
}
for(let i=0;i<12;i++){
  const y = 1.15 + i*0.52;
  slide.addShape(pptx.ShapeType.line,{x:0.25,y,w:W-0.5,h:0,line:{color:'0D3D34',transparency:86,width:0.35,dash:'dash'}});
}

// Header in original template mood
slide.addShape(pptx.ShapeType.rect,{x:0.15,y:0.18,w:12.98,h:0.78,fill:{color:C.bg2,transparency:4},line:{color:C.line,width:1.15,transparency:22}});
slide.addShape(pptx.ShapeType.line,{x:0.15,y:0.96,w:12.98,h:0,line:{color:C.red,width:2.0,transparency:0}});
addText('四大核心技术驱动康复管理闭环',0.45,0.23,6.3,0.34,{size:21,bold:true,color:C.yellow});
addText('从“功能展示”转向“技术价值展示”，让患者、家属、医生各自看到明确收益',0.47,0.62,7.4,0.20,{size:9.6,color:C.gray});
addText('CardioPilot',9.75,0.25,2.1,0.42,{size:23,bold:true,color:C.line,align:'right'});
addText('技术路线总览',11.92,0.35,0.95,0.18,{size:10.2,bold:true,color:C.yellow,align:'right'});

// Main message band
rect(0.75,1.25,11.85,0.58,'102F2A',C.line,{radius:0.08,width:1,lineTrans:34,transparency:2});
addText('核心观点',1.00,1.39,0.78,0.16,{size:10.5,bold:true,color:C.gold,align:'center'});
