addText('四项技术不是零散功能，而是围绕“科学方案—可信咨询—主动预警—长期坚持”的康复管理闭环',2.08,1.35,9.65,0.26,{size:15.2,bold:true,color:C.white,align:'center'});

// Data for four technology cards
const cards = [
  {no:'01', title:'科学干预方案生成', key:'聚焦专业，生成科学档案', sentence:'把指南与多智能体协同用于出院康复方案，解决“方案不专业、目标不清晰”。', tags:['患者：目标清晰更安心','家属：减少照护决策压力','医生：提升制定效率']},
  {no:'02', title:'安全可靠咨询', key:'降低风险，确保可信回复', sentence:'通过 MQIAG 等机制降低幻觉与错误回复，解决“问得多、答不准、不敢信”。', tags:['患者：专业解答少焦虑','家属：随时获取权威信息','医生：减少重复咨询']},
  {no:'03', title:'主动智能预警', key:'底层算法，主动干预能力', sentence:'基于生理极限与异常触发机制，提前发现风险，解决“发现晚、干预慢”。', tags:['患者：风险早发现早干预','家属：提醒及时更从容','医生：及时掌握风险']},
  {no:'04', title:'长期依从性提升', key:'异常识别，提高依从性', sentence:'识别打卡数据异常并联动心理支持，解决“长期坚持难、干预负担重”。', tags:['患者：持续支持增强信心','家属：更好陪伴支持','医生：减轻长期负担']},
];
const x1 = 0.75, x2 = 6.78, yTop = 2.08, cw=5.82, ch=1.78, gapY=0.34;
cards.forEach((d,idx)=>{
  const x = idx%2===0 ? x1 : x2;
  const y = yTop + Math.floor(idx/2)*(ch+gapY);
  // outer card
  rect(x,y,cw,ch,'0D2925',C.line,{radius:0.08,width:1.0,lineTrans:38,transparency:4});
  // left slim accent
  slide.addShape(pptx.ShapeType.rect,{x:x+0.03,y:y+0.10,w:0.055,h:ch-0.20,fill:{color:C.line,transparency:8},line:{color:C.line,transparency:100}});
  // number square muted
  rect(x+0.24,y+0.24,0.48,0.48,'143D36',C.line,{radius:0.055,width:0.8,lineTrans:25,transparency:0});
  addText(d.no,x+0.28,y+0.38,0.40,0.12,{size:12,bold:true,color:C.yellow,align:'center'});
  addText(d.title,x+0.86,y+0.20,2.85,0.26,{size:16,bold:true,color:C.mint});
  addText(d.key,x+0.86,y+0.52,2.92,0.20,{size:10.5,color:C.gray,bold:false});
  // simplified icon: small connected dots, unified color
  const ix = x+4.92, iy = y+0.22;
  slide.addShape(pptx.ShapeType.ellipse,{x:ix,y:iy,w:0.16,h:0.16,fill:{color:C.line,transparency:0},line:{color:C.line,transparency:100}});
  slide.addShape(pptx.ShapeType.ellipse,{x:ix+0.34,y:iy+0.20,w:0.16,h:0.16,fill:{color:C.line,transparency:0},line:{color:C.line,transparency:100}});
  slide.addShape(pptx.ShapeType.ellipse,{x:ix+0.10,y:iy+0.50,w:0.16,h:0.16,fill:{color:C.line,transparency:0},line:{color:C.line,transparency:100}});
  slide.addShape(pptx.ShapeType.line,{x:ix+0.12,y:iy+0.12,w:0.30,h:0.16,line:{color:C.line,width:1,transparency:20}});
  slide.addShape(pptx.ShapeType.line,{x:ix+0.42,y:iy+0.29,w:-0.22,h:0.30,line:{color:C.line,width:1,transparency:20}});
  // value sentence
  addText(d.sentence,x+0.28,y+0.88,cw-0.58,0.30,{size:10.8,color:C.white,bold:false});
  // three value chips, not table cells
  const py = y+1.30;
  pill(x+0.28,py,1.72,0.28,d.tags[0],{fill:'123B34',line:C.line,size:7.8,color:C.white,lineTrans:60});
  pill(x+2.09,py,1.74,0.28,d.tags[1],{fill:'123B34',line:C.line,size:7.8,color:C.white,lineTrans:60});
  pill(x+3.92,py,1.64,0.28,d.tags[2],{fill:'123B34',line:C.line,size:7.8,color:C.white,lineTrans:60});
});

// Bottom role summary - easier to capture than the dense table
rect(0.94,6.42,11.45,0.48,'123B34',C.line,{radius:0.08,width:0.85,lineTrans:45,transparency:4});
addText('患者获得安心康复路径',1.30,6.57,2.7,0.13,{size:10.2,bold:true,color:C.yellow,align:'center'});
addText('家属降低照护决策压力',5.25,6.57,2.7,0.13,{size:10.2,bold:true,color:C.yellow,align:'center'});
addText('医生减轻随访与干预负担',9.15,6.57,2.8,0.13,{size:10.2,bold:true,color:C.yellow,align:'center'});
slide.addShape(pptx.ShapeType.line,{x:4.45,y:6.52,w:0,h:0.28,line:{color:C.line,width:0.8,transparency:55}});
slide.addShape(pptx.ShapeType.line,{x:8.68,y:6.52,w:0,h:0.28,line:{color:C.line,width:0.8,transparency:55}});

// tiny footer line
addText('技术路线总览页：用于快速建立“四大技术优势—三方价值”的总分结构',3.00,7.10,7.4,0.13,{size:8.4,color:C.gray2,align:'center'});

warnIfSlideHasOverlaps(slide, pptx, { muteContainment: true, ignoreDecorativeShapes: true, ignoreLines: true });
warnIfSlideElementsOutOfBounds(slide, pptx);
pptx.writeFile({ fileName: '/mnt/data/四大核心技术_优化版.pptx' });
