  addText(t.desc,x+0.16,y+1.08,1.62,0.15,{size:8.1,color:C.muted});
});

// Center: fusion node and arrows, not too loud
// lines from tech cards to center
const centerX=6.62, centerY=3.24;
shape(pptx.ShapeType.chevron,{x:5.08,y:2.54,w:0.54,h:1.08,rotate:0,fill:{color:C.teal,transparency:25},line:{color:C.teal,transparency:100}});
line(4.92,3.09,0.55,0,C.teal,1.2,38);
line(4.92,3.67,0.55,0,C.teal,1.2,38);
roundRect(5.42,2.42,2.27,1.80,'0B2925',C.teal,0,20,1.1,0.10);
shape(pptx.ShapeType.ellipse,{x:5.93,y:2.64,w:1.23,h:1.23,fill:{color:'0F3A33',transparency:0},line:{color:C.teal,width:1,transparency:30}});
addText('技术\n合力',6.13,2.84,0.84,0.45,{size:19,bold:true,color:C.teal,align:'center',valign:'mid',breakLine:false});
addText('共同支撑院后康复管理闭环',5.68,4.04,1.72,0.16,{size:9.5,bold:true,color:C.yellow,align:'center'});
// arrow to right value cards
shape(pptx.ShapeType.rightArrow,{x:7.88,y:3.05,w:0.64,h:0.42,fill:{color:C.teal,transparency:5},line:{color:C.teal,transparency:100}});
line(7.68,3.25,0.25,0,C.teal,1.4,28);

// Right: three audience cards vertically, they represent combined value, less dense
const roles = [
  {role:'患者', en:'Patient', headline:'康复更安心', points:['获得个性化康复路径','可信解答减少焦虑','风险提醒与持续陪伴']},
  {role:'家属', en:'Family', headline:'照护更从容', points:['明确照护重点','随时获取权威信息','及时接收风险提醒']},
  {role:'医生', en:'Doctor', headline:'干预更精准', points:['提升方案制定效率','减少重复咨询负担','掌握院后风险状态']},
];
const ry=[2.00,3.47,4.94];
roles.forEach((r,i)=>{
  const x=8.58,y=ry[i];
  roundRect(x,y,3.98,1.14,'0D302B',C.teal,6,42,1,0.09);
  // Icon column
  shape(pptx.ShapeType.ellipse,{x:x+0.23,y:y+0.24,w:0.62,h:0.62,fill:{color:'123C35',transparency:0},line:{color:C.teal,width:1,transparency:35}});
  addText(r.role.charAt(0),x+0.405,y+0.43,0.28,0.12,{size:13,bold:true,color:C.teal,align:'center'});
  addText(r.role,x+1.02,y+0.22,0.78,0.18,{size:13,bold:true,color:C.yellow});
  addText(r.headline,x+1.74,y+0.22,1.35,0.18,{size:12.5,bold:true,color:C.teal});
  addText(r.points.join('  /  '),x+1.02,y+0.60,2.75,0.20,{size:9.2,color:C.white,fit:'shrink'});
});

// Bottom message strip: one-sentence takeaway
roundRect(1.50,6.78,10.35,0.42,'123A34',C.teal,0,35,0.9,0.07);
addText('一页核心观点：四项技术不是孤立功能，而是共同解决“专业性、可信度、风险滞后、依从性”四个院后康复痛点',1.78,6.91,9.80,0.13,{size:10.2,bold:true,color:C.yellow,align:'center'});

warnIfSlideHasOverlaps(slide, pptx, { muteContainment: true, ignoreDecorativeShapes: true, ignoreLines: true });
