bash -lc cat > /mnt/data/create_rebalanced_slide.js <<'EOF'
const pptxgen = require('pptxgenjs');
const { warnIfSlideHasOverlaps, warnIfSlideElementsOutOfBounds } = require('/home/oai/skills/slides/pptxgenjs_helpers/layout');

const pptx = new pptxgen();
pptx.defineLayout({ name:'WIDE', width:13.333, height:7.5 });
pptx.layout = 'WIDE';
pptx.author = 'OpenAI';
pptx.subject = 'CardioPilot 核心技术总览 revised';
pptx.title = '四大核心技术解决院后康复关键痛点';
pptx.company = 'OpenAI';
pptx.lang = 'zh-CN';
pptx.theme = { headFontFace: 'Microsoft YaHei', bodyFontFace: 'Microsoft YaHei', lang: 'zh-CN' };
pptx.margin = 0;

const slide = pptx.addSlide();
const W = 13.333, H = 7.5;
const C = {
  bg:'061815', bg2:'09221E', panel:'0D302B', panelDeep:'092A25', panelLite:'123A34',
  teal:'43D8BE', tealDark:'2BA78F', tealSoft:'1D6B5E', cyan:'56C7E8', yellow:'FFF0A8',
  red:'EF4846', white:'F4FFFB', muted:'B7CCC7', muted2:'86A39D', grid:'114139',
  line:'287F70'
};
function addText(txt,x,y,w,h,opts={}){
  slide.addText(txt,{x,y,w,h,fontFace:'Microsoft YaHei', margin:opts.margin ?? 0.02, fit:'shrink', breakLine:false,
    color:opts.color||C.white, bold:opts.bold||false, fontSize:opts.size||12, align:opts.align||'left', valign:opts.valign||'mid',
    ...opts});
}
function shape(type, opts){ slide.addShape(type, opts); }
function rect(x,y,w,h,fill,line=C.teal,ltrans=55,width=1,rad=0.08,trans=0){
  shape(pptx.ShapeType.roundRect,{x,y,w,h,rectRadius:rad,fill:{color:fill,transparency:trans},line:{color:line,transparency:ltrans,width}});
}
function line(x,y,w,h,color=C.line,width=1,trans=50,dash=null){
  shape(pptx.ShapeType.line,{x,y,w,h,line:{color,width,transparency:trans,dash}});
}

// Background
shape(pptx.ShapeType.rect,{x:0,y:0,w:W,h:H,fill:{color:C.bg},line:{color:C.bg,transparency:100}});
for(let i=0;i<25;i++) line(0.25+i*0.53,0.12,0,H-0.24,C.grid,0.3,83,'dash');
for(let i=0;i<15;i++) line(0.18,0.20+i*0.48,W-0.36,0,C.grid,0.3,86,'dash');
shape(pptx.ShapeType.arc,{x:-0.9,y:4.9,w:2.4,h:2.4,line:{color:C.teal,transparency:90,width:1.1},adjustPoint:0.2});
shape(pptx.ShapeType.arc,{x:12.1,y:0.95,w:2.5,h:2.5,line:{color:C.teal,transparency:91,width:1.1},adjustPoint:0.2});

// Header
shape(pptx.ShapeType.rect,{x:0.15,y:0.18,w:12.98,h:0.78,fill:{color:C.bg2,transparency:2},line:{color:C.teal,width:1.1,transparency:24}});
line(0.15,0.96,12.98,0,C.red,2,0);
addText('四大核心技术解决院后康复关键痛点',0.43,0.23,5.9,0.32,{size:21,bold:true,color:C.yellow});
addText('用技术讲清楚价值：不是功能堆叠，而是针对“方案、咨询、预警、依从性”的系统性解决方案',0.45,0.63,7.65,0.18,{size:9.2,color:C.muted});
addText('CardioPilot',9.55,0.24,2.20,0.43,{size:22.5,bold:true,color:C.teal,align:'right'});
addText('技术路线总览',11.86,0.34,0.92,0.22,{size:10,bold:true,color:C.yellow,align:'right'});

// Column headers
rect(0.60,1.34,3.05,0.38,'123A34',C.teal,42,0.8,0.06,0);
addText('核心技术',0.82,1.45,2.60,0.12,{size:12.2,bold:true,color:C.yellow,align:'center'});
rect(4.25,1.34,2.36,0.38,'123A34',C.teal,42,0.8,0.06,0);
addText('对应痛点',4.48,1.45,1.90,0.12,{size:12.2,bold:true,color:C.yellow,align:'center'});
rect(7.33,1.34,5.02,0.38,'123A34',C.teal,42,0.8,0.06,0);
addText('共同带来的三方价值',7.60,1.45,4.50,0.12,{size:12.2,bold:true,color:C.yellow,align:'center'});

// Left tech rows + pain points
const rows = [
  {n:'01', tech:'科学干预方案生成', sub:'多智能体协同 · 指南遵循', pain:'方案不够专业'},
  {n:'02', tech:'安全可靠咨询', sub:'MQ-RAG · 降低幻觉风险', pain:'咨询不够可信'},
  {n:'03', tech:'主动智能预警', sub:'生理极限建模 · 异常触发', pain:'风险发现滞后'},
  {n:'04', tech:'长期依从性提升', sub:'打卡异常识别 · 心理干预', pain:'康复难以坚持'},
];
const rowY = [2.02,2.95,3.88,4.81];
rows.forEach((r,i)=>{
  const y=rowY[i];
  rect(0.60,y,3.05,0.64,C.panel,C.teal,48,0.9,0.07,4);
  shape(pptx.ShapeType.ellipse,{x:0.80,y:y+0.17,w:0.32,h:0.32,fill:{color:C.teal,transparency:4},line:{color:C.teal,transparency:100}});
  addText(r.n,0.86,y+0.25,0.20,0.06,{size:7.8,bold:true,color:'06231F',align:'center'});
  addText(r.tech,1.24,y+0.13,2.15,0.17,{size:11.5,bold:true,color:C.white});
  addText(r.sub,1.24,y+0.39,2.18,0.14,{size:8.2,color:C.muted});
  // arrow to pain point
  line(3.72,y+0.32,0.42,0,C.teal,1.1,40);
  shape(pptx.ShapeType.triangle,{x:4.07,y:y+0.26,w:0.12,h:0.12,rotate:90,fill:{color:C.teal,transparency:8},line:{color:C.teal,transparency:100}});
  rect(4.25,y,2.36,0.64,C.panelDeep,C.teal,48,0.9,0.07,7);
  addText(r.pain,4.52,y+0.19,1.82,0.18,{size:12.4,bold:true,color:C.yellow,align:'center'});
});

// Connector from pain points to value panel: subdued, not a big node
line(6.75,3.27,0.40,0,C.teal,1.2,45);
shape(pptx.ShapeType.rightArrow,{x:6.98,y:3.02,w:0.42,h:0.50,fill:{color:C.teal,transparency:16},line:{color:C.teal,transparency:100}});
addText('形成院后康复管理闭环',5.05,5.65,1.65,0.15,{size:8.6,color:C.muted2,align:'center'});

// Right combined value panel
rect(7.33,1.96,5.02,3.96,C.panel,C.teal,38,1.0,0.10,4);
addText('四项技术共同作用，最终不是展示“APP功能”，而是提升三方体验',7.68,2.20,4.25,0.22,{size:12.3,bold:true,color:C.yellow,align:'center'});
line(7.70,2.55,4.25,0,C.teal,0.9,60);

const vals = [
  {role:'患者', head:'康复更安心', detail:'个性化路径 + 可信解答 + 风险提醒'},
  {role:'家属', head:'照护更省心', detail:'明确照护重点 + 权威信息 + 及时提醒'},
  {role:'医生', head:'管理更高效', detail:'方案制定更快 + 咨询负担更低 + 风险掌握更及时'},
];
const vy=[2.85,3.75,4.65];
vals.forEach((v,i)=>{
  const y=vy[i];
  // subtle separator/card
  rect(7.72,y,4.25,0.66,'0A2924',C.teal,62,0.6,0.07,4);
  shape(pptx.ShapeType.ellipse,{x:7.98,y:y+0.16,w:0.34,h:0.34,fill:{color:'123A34',transparency:0},line:{color:C.teal,transparency:45,width:0.8}});
  addText(v.role.charAt(0),8.06,y+0.25,0.18,0.06,{size:8,bold:true,color:C.teal,align:'center'});
  addText(v.role,8.52,y+0.13,0.58,0.16,{size:11.4,bold:true,color:C.yellow});
  addText(v.head,9.20,y+0.13,1.20,0.16,{size:11.6,bold:true,color:C.teal});
  addText(v.detail,8.52,y+0.39,3.15,0.13,{size:8.2,color:C.muted});
});

// Bottom takeaway, smaller and cleaner
rect(1.35,6.62,10.65,0.46,'0D302B',C.teal,48,0.8,0.07,0);
addText('一句话：四大核心技术分别补齐院后康复的“专业性、可信度、及时性、持续性”短板。',1.70,6.76,9.95,0.15,{size:10.5,bold:true,color:C.yellow,align:'center'});

warnIfSlideHasOverlaps(slide, pptx, { muteContainment: true, ignoreDecorativeShapes: true, ignoreLines: true });
warnIfSlideElementsOutOfBounds(slide, pptx);
pptx.writeFile({ fileName: '/mnt/data/四大核心技术_再调整版.pptx' });
EOF
